import * as Cesium from 'cesium';

function FadeMaterialProperty(options = {}) {
  this._definitionChanged = new Cesium.Event();
  this._color = options.color || Cesium.Color.WHITE;
  this._center = new Cesium.Cartesian2((options.center && options.center.x) || 0.5, (options.center && options.center.y) || 0.5);
  this._power = options.power || 0.25;
  this._stretch = options.stretch || 1;
  this.color = this._color;
  this.center = this._center;
  this.power = this._power;
  this.stretch = this._stretch;
}

Object.defineProperties(FadeMaterialProperty.prototype, {
  isConstant: {
    get: function () {
      return Cesium.Property.isConstant(this._color) &&
             Cesium.Property.isConstant(this._center) &&
             Cesium.Property.isConstant(this._power) &&
             Cesium.Property.isConstant(this._stretch);
    }
  },
  color: Cesium.createPropertyDescriptor('color'),
  center: Cesium.createPropertyDescriptor('center'),
  power: Cesium.createPropertyDescriptor('power'),
  stretch: Cesium.createPropertyDescriptor('stretch'),
  definitionChanged: {
    get: function () {
      return this._definitionChanged;
    }
  }
});

FadeMaterialProperty.prototype.getType = function (time) {
  return 'Fade';
};

FadeMaterialProperty.prototype.getValue = function (time, result) {
  if (!Cesium.defined(result)) {
    result = {};
  }
  result.color = Cesium.Property.getValueOrClonedDefault(this._color, time, Cesium.Color.WHITE, result.color);
  result.center = Cesium.Property.getValueOrClonedDefault(this._center, time, new Cesium.Cartesian2(0.5, 0.5), result.center);
  result.power = Cesium.Property.getValueOrClonedDefault(this._power, time, 0.25, result.power);
  result.stretch = Cesium.Property.getValueOrClonedDefault(this._stretch, time, 1, result.stretch);
  return result;
};

FadeMaterialProperty.prototype.equals = function (other) {
  return this === other ||
         (other instanceof FadeMaterialProperty &&
          Cesium.Property.equals(this._color, other._color) &&
          Cesium.Property.equals(this._center, other._center) &&
          Cesium.Property.equals(this._power, other._power) &&
          Cesium.Property.equals(this._stretch, other._stretch));
};

Cesium.Material.FadeMaterialType = 'Fade';

Cesium.Material.FadeMaterialProperty = FadeMaterialProperty;

Cesium.Material._materialCache.addMaterial(Cesium.Material.FadeMaterialType, {
  fabric: {
    type: 'Fade',
    uniforms: {
      color: Cesium.Color.WHITE,
      center: { x: 0.5, y: 0.5 },
      power: 0.25,
      stretch: 1
    },
    source: "\n      czm_material czm_getMaterial(czm_materialInput materialInput) {\n        czm_material material = czm_getDefaultMaterial(materialInput);\n        vec2 coords = materialInput.st;\n        float distance = distance(coords, center);\n        vec4 fragColor = czm_gammaCorrect(color.rgba);\n        material.diffuse = fragColor.rgb;\n        material.alpha = smoothstep(0.0, 1.0, distance);\n        if (stretch == 1.0) {\n          material.alpha = smoothstep(0.0, 1.0, distance);\n        } else if (stretch == 2.0) {\n          material.alpha = log(1.0 + distance);\n        } else if (stretch == 3.0) {\n          material.alpha = pow(distance, 2.0);\n        } else if (stretch == 4.0) {\n          material.alpha = pow(log(1.0 + distance), 2.0);\n        } else {\n          material.alpha = color.a;\n        }\n        material.emission = vec3(power);\n        return material;\n      }\n    "
  },
  translucent: function (material) {
    return true;
  }
});

export default FadeMaterialProperty;

